    def __init__(self, size):
        self.size = size
        self.slots = [None] * size

    def insert(self, key):
        index = key % self.size
        while self.slots[index] != None:
            index = (index + 1) % self.size
        self.slots[index] = key

    def find(self, key):
        index = key % self.size
        while self.slots[index] != None:
            if self.slots[index] == key:
                return index
            index = (index + 1) % self.size
        return -1

